package net.zartra.gui;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import org.bukkit.potion.*;import java.io.*;import java.util.*;
final class ActionExecutor { static final class Context { final Player player;final MenuDefinition menu;final Set<String> path;Context(Player p,MenuDefinition m,Set<String> q){player=p;menu=m;path=q;} } private final ZartraGUIPlugin plugin;private final MenuManager menus;private final PlaceholderService placeholders=new PlaceholderService();private final ConditionEvaluator conditions;private final VariableStore variables;private final CooldownManager cooldowns=new CooldownManager();private final ActionRegistry registry=new ActionRegistry();private final VaultAdapter vault=new VaultAdapter();ActionExecutor(ZartraGUIPlugin p,MenuManager m){plugin=p;menus=m;variables=p==null?new VariableStore():p.variables();conditions=new ConditionEvaluator(variables,new PlaceholderService(variables));for(final MenuAction.Type type:MenuAction.Type.values())registry.register(type.name(),type.name().replace('_',' '),type!=MenuAction.Type.CLOSE_MENU&&type!=MenuAction.Type.REFRESH_MENU&&type!=MenuAction.Type.HEAL&&type!=MenuAction.Type.FEED&&type!=MenuAction.Type.CLEAR_POTION_EFFECTS,new ActionRegistry.Handler(){public boolean execute(Context c,String v)throws Exception{return executeKnown(type.name(),c,v);}});}ActionRegistry registry(){return registry;}
 boolean conditionsPass(Player p,MenuDefinition menu,ConditionSet set){return conditions.testSet(p,menu,set);} void run(Player p,MenuDefinition menu,List<ActionEntry> actions){Set<String> path=new HashSet<String>();path.add(menu.id);run(p,menu,actions,0,0,path);} boolean ready(Player p,MenuDefinition d,int slot,MenuItem item){return cooldowns.ready(p.getUniqueId(),d.id+":"+slot,item.cooldown);} private void run(final Player p,final MenuDefinition m,final List<ActionEntry>a,final int i,long wait,final Set<String> path){if(i>=a.size()||!p.isOnline()||i>64)return;final ActionEntry x=a.get(i);Runnable r=new Runnable(){public void run(){if(!p.isOnline())return;if("WAIT".equals(x.type)){long ticks=ActionSequencing.waitTicks(placeholders.replace(p,m,x.value));if(ticks<0){if(!x.stopOnFailure)ActionExecutor.this.run(p,m,a,i+1,0,path);}else ActionExecutor.this.run(p,m,a,i+1,ticks,path);return;}boolean ok=exec(p,m,x,path);if(ActionSequencing.continueAfter(ok,x))ActionExecutor.this.run(p,m,a,i+1,0,path);}};long d=ActionSequencing.delay(wait,x);if(d>0)Bukkit.getScheduler().runTaskLater(plugin,r,d);else r.run();}
 private boolean exec(Player p,MenuDefinition m,ActionEntry a,Set<String> path){if(!a.enabled)return true;if(!ActionValidator.chance(a.chance)){plugin.getLogger().warning("Invalid chance in action "+a.id);return false;}if(Math.random()*100D>a.chance)return true;if(!conditions.testEntries(p,m,a.conditions,a.conditionMode)){if(!a.conditionFailureMessage.isEmpty())p.sendMessage(Chat.c(a.conditionFailureMessage));if(!a.failureActions.isEmpty())run(p,m,a.failureActions);return false;}if(!a.successActions.isEmpty())run(p,m,a.successActions);ActionRegistry.Definition def=registry.get(a.type);if(def==null){plugin.getLogger().warning("Unknown action type "+a.type);return false;}String v=Chat.c(placeholders.replace(p,m,a.value));try{return def.handler.execute(new Context(p,m,path),v);}catch(Exception e){plugin.getLogger().warning("Action "+a.type+" failed: "+e.getMessage());return false;}}
 private boolean executeKnown(String type,Context c,String v)throws Exception{Player p=c.player;MenuDefinition m=c.menu;if("PLAYER_COMMAND".equals(type)){p.performCommand(strip(v));return true;}if("CONSOLE_COMMAND".equals(type)){Bukkit.dispatchCommand(Bukkit.getConsoleSender(),strip(v));return true;}if("OP_COMMAND".equals(type)){boolean op=p.isOp();try{p.setOp(true);p.performCommand(strip(v));}finally{p.setOp(op);}return true;}if("MESSAGE".equals(type)){p.sendMessage(v);return true;}if("BROADCAST".equals(type)){Bukkit.broadcastMessage(v);return true;}if("ACTION_BAR".equals(type)){p.sendMessage(v);return true;}if("CLOSE_MENU".equals(type)){p.closeInventory();return true;}if("REFRESH_MENU".equals(type)){menus.open(p,m);return true;}if("OPEN_MENU".equals(type)){MenuDefinition n=menus.get(stripColor(v));if(n==null||c.path.contains(n.id))return false;c.path.add(n.id);menus.open(p,n);return true;}if("CONNECT_SERVER".equals(type)){String server=stripColor(v);if(!ActionValidator.serverName(server)){p.sendMessage(Chat.c("&cInvalid proxy server name."));return false;}ByteArrayOutputStream out=new ByteArrayOutputStream();DataOutputStream data=new DataOutputStream(out);data.writeUTF("Connect");data.writeUTF(server);p.sendPluginMessage(plugin,"BungeeCord",out.toByteArray());return true;}if("GIVE_ITEM".equals(type)){p.getInventory().addItem(new ItemStack(CompatMaterial.find(stripColor(v))));return true;}if("HEAL".equals(type)){p.setHealth(p.getMaxHealth());return true;}if("FEED".equals(type)){p.setFoodLevel(20);return true;}if("SET_HEALTH".equals(type)){p.setHealth(Math.max(0,Math.min(p.getMaxHealth(),Double.parseDouble(v))));return true;}if("SET_FOOD".equals(type)){p.setFoodLevel(Math.max(0,Math.min(20,Integer.parseInt(v))));return true;}if("SET_FLY".equals(type)){p.setAllowFlight(Boolean.parseBoolean(v));return true;}if("CLEAR_POTION_EFFECTS".equals(type)){for(PotionEffect e:p.getActivePotionEffects())p.removePotionEffect(e.getType());return true;}if("SOUND".equals(type)){p.playSound(p.getLocation(),Sound.valueOf(stripColor(v).toUpperCase()),1F,1F);return true;}if("TELEPORT_WORLD".equals(type)){World w=Bukkit.getWorld(stripColor(v));if(w==null)return false;p.teleport(w.getSpawnLocation());return true;}if("TELEPORT".equals(type)){String[] q=stripColor(v).split(",");if(q.length<3)return false;World w=q.length>3?Bukkit.getWorld(q[3]):p.getWorld();if(w==null)return false;p.teleport(new Location(w,Double.parseDouble(q[0]),Double.parseDouble(q[1]),Double.parseDouble(q[2])));return true;}if("SET_GAMEMODE".equals(type)){p.setGameMode(GameMode.valueOf(stripColor(v).toUpperCase()));return true;}if("POTION_EFFECT".equals(type)){String[] q=stripColor(v).split(":");PotionEffectType pt=PotionEffectType.getByName(q[0].toUpperCase());if(pt==null)return false;p.addPotionEffect(new PotionEffect(pt,q.length>1?Integer.parseInt(q[1]):200,q.length>2?Integer.parseInt(q[2]):0));return true;}if("REMOVE_POTION_EFFECT".equals(type)){PotionEffectType pt=PotionEffectType.getByName(stripColor(v).toUpperCase());if(pt==null)return false;p.removePotionEffect(pt);return true;}if("SET_VARIABLE".equals(type))return variables.apply(p.getUniqueId(),m.id,stripColor(v),"SET");if("ADD_VARIABLE".equals(type))return variables.apply(p.getUniqueId(),m.id,stripColor(v),"ADD");if("REMOVE_VARIABLE".equals(type))return variables.apply(p.getUniqueId(),m.id,stripColor(v),"REMOVE");if("TOGGLE_VARIABLE".equals(type))return variables.apply(p.getUniqueId(),m.id,stripColor(v),"TOGGLE");if("GIVE_MONEY".equals(type)){if(!VaultAdapter.validAmount(v))return false;return vault.deposit(p,Double.parseDouble(v));}if("TAKE_MONEY".equals(type)){if(!VaultAdapter.validAmount(v))return false;return vault.withdraw(p,Double.parseDouble(v));}if("SET_MONEY".equals(type)){return VaultAdapter.validAmount(v)&&vault.setBalance(p,Double.parseDouble(v));}if("ADD_PERMISSION".equals(type))return VaultAdapter.validNode(stripColor(v))&&vault.permission(p,stripColor(v),true);if("REMOVE_PERMISSION".equals(type))return VaultAdapter.validNode(stripColor(v))&&vault.permission(p,stripColor(v),false);if("WAIT".equals(type))return ActionValidator.delay(parse(v));return false;}
 private String strip(String s){return s.startsWith("/")?s.substring(1):s;}private String stripColor(String s){return ChatColor.stripColor(s);}private long parse(String s){try{return Long.parseLong(s);}catch(Exception e){return -1;}}
}